#!/usr/bin/env node
import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = import.meta.dirname;
const port = 4700 + Math.floor(Math.random() * 200);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 500));

let ok = true;
function check(name, cond) {
  console.log(`${cond ? 'PASS' : 'FAIL'}: ${name}`);
  if (!cond) ok = false;
}

try {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));

  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'load' });
  await page.waitForTimeout(300);

  // seed data rendered
  const notes = await page.$$('#feed article.note');
  check('6 seed notes rendered', notes.length === 6);

  // rich text: bold and link render correctly
  const boldHtml = await page.$eval('article[data-note-id="1"] .note-body', (el) => el.innerHTML);
  check('bold tag rendered as <b>', /<b>OWASP AppSec Days Porto<\/b>/.test(boldHtml));
  check('br rendered', /<br>/.test(boldHtml));

  const linkHref = await page.$eval('article[data-note-id="4"] .note-body a', (el) => el.getAttribute('href'));
  check('link href preserved', linkHref === 'https://www.livrarialello.pt/');

  // avatar rendering
  const avatarSrc = await page.$eval('article[data-note-id="1"] img.note-avatar', (el) => el.getAttribute('src'));
  check('avatar rendered', !!avatarSrc && avatarSrc.startsWith('data:image/svg+xml'));

  // search
  await page.fill('#search', 'Douro');
  await page.waitForTimeout(150);
  const resultsLine = await page.$eval('#results-line', (el) => el.textContent);
  check('results line shows query', resultsLine === 'results for "Douro"');
  const filteredCount = await page.$$eval('#feed article.note', (els) => els.length);
  check('search filters notes', filteredCount === 2);
  let hash = await page.evaluate(() => location.hash);
  check('hash has q param', hash === '#q=Douro');

  // select a note while searching
  await page.click('article[data-note-id="2"] .note-title');
  await page.waitForTimeout(150);
  hash = await page.evaluate(() => location.hash);
  check('hash combines q and note', hash === '#q=Douro&note=2');
  const ariaCurrent = await page.$eval('article[data-note-id="2"]', (el) => el.getAttribute('aria-current'));
  check('selected note has aria-current=true', ariaCurrent === 'true');

  // reload restores state from hash
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(300);
  const searchVal = await page.$eval('#search', (el) => el.value);
  check('search restored after reload', searchVal === 'Douro');
  const ariaCurrent2 = await page.$eval('article[data-note-id="2"]', (el) => el.getAttribute('aria-current'));
  check('selection restored after reload', ariaCurrent2 === 'true');

  // clear search
  await page.fill('#search', '');
  await page.waitForTimeout(150);
  const resultsLineEmpty = await page.$eval('#results-line', (el) => el.textContent);
  check('results line empty when no query', resultsLineEmpty === '');

  // add a note with XSS attempt + rich text
  await page.fill('#title', 'Test <script>window.__xss=1</script> Title');
  await page.fill('#body', 'Hello <b>World</b> visit <a href="javascript:alert(1)">evil</a> and <a href="https://example.com">good</a>\nnewline');
  await page.fill('#avatar', 'javascript:alert(2)');
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(200);

  const xssTriggered = await page.evaluate(() => window.__xss === 1);
  check('script tag did NOT execute', !xssTriggered);

  const newNoteBody = await page.$eval('article:last-child .note-body, #feed article:first-child .note-body', () => '').catch(() => '');
  // find the note with the new title text (search-cleared, newest first so it should be first)
  const firstBodyHtml = await page.$eval('#feed article.note:first-child .note-body', (el) => el.innerHTML);
  console.log('new note body html:', firstBodyHtml);
  check('bold in new note rendered', /<b>World<\/b>/.test(firstBodyHtml));
  check('javascript: href stripped', !/javascript:/i.test(firstBodyHtml));
  check('safe href preserved', /href="https:\/\/example\.com"/.test(firstBodyHtml));
  check('newline converted to <br>', /newline/.test(firstBodyHtml) && /<br>/.test(firstBodyHtml));

  const firstTitleHtml = await page.$eval('#feed article.note:first-child .note-title', (el) => el.innerHTML);
  check('script tag escaped in title, not executed as element', !firstTitleHtml.includes('<script>'));

  const avatarAfterAdd = await page.$('#feed article.note:first-child img.note-avatar');
  check('javascript: avatar URL rejected (no img rendered)', avatarAfterAdd === null);

  const titleValAfterSubmit = await page.$eval('#title', (el) => el.value);
  check('form cleared after submit', titleValAfterSubmit === '');

  check('no console/page errors', errors.length === 0);
  if (errors.length) console.log('errors:', errors);

  await browser.close();
} finally {
  server.kill();
}

console.log(ok ? 'ALL PASS' : 'SOME FAILED');
process.exit(ok ? 0 : 1);

